@js:
var end = java.getString("text.末页@value");
java.log(end);
var endn = end.match(/index_(\d+)/);
if (endn && endn[1]) {
endn = Number(endn[1]);
}else{endn=""}
var list = [];
for (var i = 2; i <= endn; i++) {
    var url = book.tocUrl;
    list.push(url + "index_" + i + '.html');
}
list;

